/**
 * Schema barrel — re-exports all feature schemas from the main schema file.
 * Import one place, get everything.
 */
export {
  // ── Composable column primitives ──────────────────────────────
  lineItemColumns,
  bicycleLineColumns,
  lineItemChecks,

  // ── Core entities ────────────────────────────────────────────
  customers, users, vatRates,

  // ── Catalog ──────────────────────────────────────────────────
  parts, laborServices, bicycleTemplates,

  // ── Bicycles ─────────────────────────────────────────────────
  bicycles,

  // ── Working documents ────────────────────────────────────────
  quotes, quoteLineItems,
  repairs, repairLineItems, workLogs, repairStatusHistory,
  customerOrders, customerOrderLineItems,
  backorders, backorderLineItems, backorderStatusHistory,

  // ── Final documents ──────────────────────────────────────────
  sales, saleLineItems, invoices, invoiceLineItems,

  // ── Payments ─────────────────────────────────────────────────
  payments, paymentAllocations,

  // ── Supplier & inventory ─────────────────────────────────────
  supplierProducts, supplierOrders, supplierOrderLines, stockMovements,

  // ── Notifications ────────────────────────────────────────────
  notifications,

} from '../schema'

// ── Belgian Address Data (modular schema) ───────────────────────
export {
  postalCodes, addressStreets, addressSyncMetadata,
} from './address'

export type {
  // ── Core entities ────────────────────────────────────────────
  Customer, NewCustomer,
  User, NewUser,
  VatRate, NewVatRate,

  // ── Catalog ──────────────────────────────────────────────────
  Part, NewPart,
  LaborService, NewLaborService,
  BicycleTemplate, NewBicycleTemplate,

  // ── Bicycles ─────────────────────────────────────────────────
  Bicycle, NewBicycle,

  // ── Working documents ────────────────────────────────────────
  Quote, NewQuote,
  QuoteLineItem, NewQuoteLineItem,
  Repair, NewRepair,
  RepairLineItem, NewRepairLineItem,
  WorkLog, NewWorkLog,
  RepairStatusHistory, NewRepairStatusHistory,
  CustomerOrder, NewCustomerOrder,
  CustomerOrderLineItem, NewCustomerOrderLineItem,
  Backorder, NewBackorder,
  BackorderLineItem, NewBackorderLineItem,
  BackorderStatusHistory, NewBackorderStatusHistory,

  // ── Final documents ──────────────────────────────────────────
  Sale, NewSale,
  SaleLineItem, NewSaleLineItem,
  Invoice, NewInvoice,
  InvoiceLineItem, NewInvoiceLineItem,

  // ── Payments ─────────────────────────────────────────────────
  Payment, NewPayment,
  PaymentAllocation, NewPaymentAllocation,

  // ── Supplier & inventory ─────────────────────────────────────
  SupplierProduct, NewSupplierProduct,
  SupplierOrder, NewSupplierOrder,
  SupplierOrderLine, NewSupplierOrderLine,
  StockMovement, NewStockMovement,

  // ── Notifications ────────────────────────────────────────────
  Notification, NewNotification,
} from '../schema'

// ── Belgian Address Data (modular schema) — types ───────────────
export type {
  PostalCode, NewPostalCode,
  AddressStreet, NewAddressStreet,
  AddressSyncMetadata, NewAddressSyncMetadata,
} from './address'

/** Estimates/proposals — immutable once sent. Copied to Order or Repair on approval. */
export const quotes = sqliteTable('quotes', {
  id: text('id').primaryKey(),
  quoteNumber: text('quote_number').notNull().unique(), // QT-0001
  customerId: text('customer_id').references(() => customers.id), // nullable during draft
  status: text('status', { enum: ['draft', 'sent', 'converted', 'rejected'] })
    .notNull().default('draft'),
  notes: text('notes'),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  statusIdx: index('quotes_status_idx').on(table.status),
  customerRequiredCheck: check(
    'quotes_customer_required_check',
    sql`${sql.identifier('status')} = 'draft' OR ${sql.identifier('customer_id')} IS NOT NULL`
  ),
}))

export type Quote = typeof quotes.$inferSelect
export type NewQuote = typeof quotes.$inferInsert

/** Quote line items — snapshotted pricing per line */
export const quoteLineItems = sqliteTable('quote_line_items', {
  id: text('id').primaryKey(),
  quoteId: text('quote_id').notNull().references(() => quotes.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  quoteIdIdx: index('quote_line_items_quote_id_idx').on(table.quoteId),
  ...lineItemChecks(),
}))

export type QuoteLineItem = typeof quoteLineItems.$inferSelect
export type NewQuoteLineItem = typeof quoteLineItems.$inferInsert

