import { z } from 'zod'

/** Payment method accepted at checkout */
export const paymentMethodSchema = z.enum(['cash', 'card'])

export type PaymentMethod = z.infer<typeof paymentMethodSchema>

/** A single line item in a sale cart / creation request */
export const cartLineItemSchema = z.object({
  /** Part ID to sell */
  partId: z.string().min(1, 'partId is required'),
  /** Number of units to sell (must be positive) */
  quantity: z.number().int().positive('quantity must be a positive integer'),
  /** Net unit price in cents (snapshot at time of sale) */
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be non-negative'),
  /** VAT rate ID — references vatRates table */
  vatRateId: z.string().min(1, 'vatRateId is required'),
  /** Human-readable description (snapshot at time of sale) */
  description: z.string().min(1, 'description is required').max(500),
  /** Discount in basis points — null means no discount */
  discountPercent: z.number().int().nonnegative().nullable().optional(),
})

export type CartLineItem = z.infer<typeof cartLineItemSchema>

/** Full input for creating a direct sale at checkout */
export const createDirectSaleInputSchema = z.object({
  /** Optional customer ID — null/absent means walk-in */
  customerId: z.string().nullable().optional(),
  /** Payment method for the full amount */
  paymentMethod: paymentMethodSchema,
  /** Line items being purchased */
  lineItems: z.array(cartLineItemSchema).min(1, 'At least one line item is required'),
})

export type CreateDirectSaleInput = z.infer<typeof createDirectSaleInputSchema>

/**
 * Explicit TypeScript interfaces for repair-related entities.
 * Mirrors the DB schema but is decoupled from Drizzle inference.
 * Both client and server import these as single source of truth.
 */

// ============================================================================
// Repair Status — lifecycle states
// ============================================================================

export type RepairStatus = 'intake' | 'in_progress' | 'on_hold' | 'verified' | 'ready' | 'completed' | 'cancelled'

/** Valid status transitions from a given source status */
export const VALID_TRANSITIONS: Record<RepairStatus, RepairStatus[]> = {
  intake: ['in_progress'],
  in_progress: ['on_hold', 'verified'],
