/** Create a new repair via the intake flow. */
export async function createRepair(input: RepairIntakeInput): Promise<RepairDetail> {
  const response = await fetch('/api/repairs', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Failed to create repair' }))
    throw new Error(error.error || 'Failed to create repair')
  }

  return response.json()
}

/** Get a single repair by ID. */
export async function getRepair(id: string): Promise<RepairDetail> {
  const response = await fetch(`/api/repairs/${id}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repair')
  }

  return response.json()
}

