import type { Context } from 'hono'
import * as z from 'zod'

// ---------------------------------------------------------------------------
// Unified Error Response Format
//
// All API errors follow this structure:
//   { error: string, code: string }
//
// Usage in routes:
//   return c.jsonError('Todo not found', 404, 'NOT_FOUND')
//   return c.jsonBadRequest(validation.error.errors[0].message)
// ---------------------------------------------------------------------------

export type ErrorCode =
  | 'INTERNAL_ERROR'
  | 'BAD_REQUEST'
  | 'UNAUTHORIZED'
  | 'FORBIDDEN'
  | 'NOT_FOUND'
  | 'CONFLICT'
  | 'VALIDATION_ERROR'
  | 'DATABASE_ERROR'
  | 'SERVICE_UNAVAILABLE'

export interface ApiError {
  error: string
  code: ErrorCode
}

/**
 * Create a structured API error response.
 */
function createApiError(message: string, code: ErrorCode): ApiError {
  return { error: message, code }
}

// ---------------------------------------------------------------------------
// Hono context extensions — attach these to Context in middleware or globally
// ---------------------------------------------------------------------------

declare module 'hono' {
  interface Context {
    jsonError(message: string, status: number, code?: ErrorCode): Response
    jsonBadRequest(message: string): Response
    jsonNotFound(resource?: string): Response
    jsonConflict(message: string): Response
    jsonUnauthorized(message?: string): Response
    jsonForbidden(message?: string): Response
  }
}

// ---------------------------------------------------------------------------
// Implementation — these are called on `c` (Context)
// ---------------------------------------------------------------------------

export function extendContext(c: Context): void {
  const jsonErr = (msg: string, status: number, code: ErrorCode) => {
    return new Response(JSON.stringify(createApiError(msg, code)), { status, headers: { 'Content-Type': 'application/json' } })
  }

  c.jsonError = function (message: string, status: number, code: ErrorCode = 'INTERNAL_ERROR'): Response {
    return jsonErr(message, status, code)
  }

  c.jsonBadRequest = function (message: string): Response {
    return jsonErr(message, 400, 'BAD_REQUEST')
  }

  c.jsonNotFound = function (resource: string = 'Resource'): Response {
    return jsonErr(`${resource} not found`, 404, 'NOT_FOUND')
  }

  c.jsonConflict = function (message: string): Response {
    return jsonErr(message, 409, 'CONFLICT')
  }

  c.jsonUnauthorized = function (message: string = 'Authentication required'): Response {
    return jsonErr(message, 401, 'UNAUTHORIZED')
  }

  c.jsonForbidden = function (message: string = 'Access denied'): Response {
    return jsonErr(message, 403, 'FORBIDDEN')
  }
}

// ---------------------------------------------------------------------------
// Validation error formatter — converts Zod errors to user-friendly messages
// ---------------------------------------------------------------------------

export function formatZodError(error: z.ZodError): string {
  const first = error.errors[0]
  if (!first) return 'Validation failed'

  // Build a readable message with field path and issue type
  const field = first.path.join('.') || '(root)'
  return `${field}: ${first.message}`
}

// ---------------------------------------------------------------------------
// Database error classifier — maps DB errors to appropriate codes
// ---------------------------------------------------------------------------

export function classifyDbError(error: unknown): ErrorCode {
  const message = String(error)

  // SQLite constraint violations
  if (message.includes('UNIQUE constraint failed') || message.includes('FOREIGN KEY constraint failed')) {
    return 'CONFLICT'
  }

  // Database connection / corruption
  if (message.includes('database is locked') || message.includes('unable to open database')) {
    return 'SERVICE_UNAVAILABLE'
  }

  // Default — treat as internal error
