interface CurrencyInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'onChange' | 'value'> {
  /** Current value in cents (integer) */
  value: number
  /** Change callback — receives new value in cents */
  onChange: (cents: number) => void
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * CurrencyInput — accepts decimal euros, converts to/from cents.
 *
 * Displays values as €X.XX but stores them internally as integer cents.
 * This prevents floating-point precision issues while providing a familiar
 * euro-formatted display for users.
 */
export function CurrencyInput({ value, onChange, className, ...props }: CurrencyInputProps) {
  const [displayValue, setDisplayValue] = React.useState(formatCentsToEuro(value))

  // Update display when cents change externally
  React.useEffect(() => {
    setDisplayValue(formatCentsToEuro(value))
  }, [value])

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.value

    // Allow empty input during typing
    if (raw === '' || raw === '-') {
      onChange(0)
      return
    }

    // Parse decimal euros → cents
    const euroValue = parseFloat(raw.replace(',', '.'))
    if (isNaN(euroValue) || euroValue < 0) {
      return
    }

    const cents = Math.round(euroValue * 100)
    onChange(cents)
  }

  const handleBlur = () => {
    // Format to 2 decimal places on blur
    setDisplayValue(formatCentsToEuro(value))
  }

  return (
    <div className="relative">
      <input
        type="text"
        inputMode="decimal"
        value={displayValue}
        onChange={handleChange}
        onBlur={handleBlur}
        className={`h-10 w-full rounded-md border border-input bg-background pl-3 pr-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 ${className ?? ''}`}
        {...props}
      />
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/** Generate a unique ID for optimistic UI updates.
 * Works in both browser and Node.js without crypto.randomUUID(). */
export function generateId(): string {
  return Math.random().toString(36).substring(2) + Date.now().toString(36)
}

/** Format cents (integer) to Euro string with 2 decimal places. */
export function formatCentsToEuro(cents: number): string {
  return `€${(cents / 100).toFixed(2)}`
}
